// Lógica de cálculo corporativo de SLA e enriquecimento de políticas de suporte
const inputData = $input.first().json;

const severity = (inputData.severity || 'Media').toLowerCase();
const category = inputData.category || 'Outros';
const ticketId = inputData.ticket_id || 'TCK-UNKNOWN';
const userEmail = inputData.user_email || 'usuario@empresa.com';

// Matriz formal de SLA por severidade (em minutos)
const slaMatrix = {
  'critica': 30,
  'alta': 120,
  'media': 480,
  'baixa': 1440
};

const slaMinutes = slaMatrix[severity] || 480;

// Determina a equipe técnica responsável e nível de escalonamento
let assignedTeam = 'N1 Suporte Geral';
let escalationTier = 'N1_LOCAL';
let onCallRequired = false;

if (category === 'Acessos/Senhas') {
  assignedTeam = 'N2 Acessos e Identidade';
  escalationTier = 'N2_AUTOMATED_REMEDIATION';
} else if (category === 'Redes/VPN') {
  assignedTeam = 'N2 Infraestrutura e Redes';
  escalationTier = 'N2_NETWORK_FAILOVER';
} else if (category === 'Hardware') {
  assignedTeam = 'Suporte Presencial N2';
  escalationTier = 'N2_ONSITE_FIELD_SERVICE';
}

if (severity === 'critica') {
  onCallRequired = true;
  escalationTier = 'N3_PLANTÃO_IMEDIATO';
}

// Cálculo de deadline com base no horário atual
const now = new Date();
const deadlineDate = new Date(now.getTime() + slaMinutes * 60000);

return [{
  json: {
    subworkflow_executed: true,
    subworkflow_version: 'v4.0.0',
    ticket_id: ticketId,
    user_email: userEmail,
    category: category,
    severity: inputData.severity || 'Media',
    sla_target_minutes: slaMinutes,
    sla_deadline_iso: deadlineDate.toISOString(),
    assigned_team: assignedTeam,
    escalation_tier: escalationTier,
    on_call_required: onCallRequired,
    compliance_rule_applied: 'SOP-ITSM-POL-04',
    calculated_at: now.toISOString()
  }
}];

const item = $input.first().json;
item.priority_notification = 'PAGERDUTY_ALERT_TRIGGERED';
item.sla_badge = 'CRITICAL_URGENT';
return [{ json: item }];

const item = $input.first().json;
item.priority_notification = 'STANDARD_QUEUE';
item.sla_badge = 'NORMAL_FLOW';
return [{ json: item }];
